class TurtleLexer extends LrLexer {
  public constructor(input: string) {
    super(input, LEXER_RULES);
  }

  override performAction(rule: number): number {
    switch (rule) {
      case 0: // ignore
        return 0;
      case 1: // PREFIX_ID
        return 6;
      case 2: // BASE_ID
        return 11;
      case 3: // VERSION_ID
        return 13;
      case 4: // SPARQL_PREFIX
        return 10;
      case 5: // SPARQL_BASE
        return 12;
      case 6: // SPARQL_VERSION
        return 15;
      case 7: // GRAPH
        return 20;
      case 8: // a
        return 55;
      case 9: // BOOLEAN
        return 68;
      case 10: // ^^
        return 64;
      case 11: // <<(
        return 79;
      case 12: // )>>
        return 82;
      case 13: // <<
        return 87;
      case 14: // >>
        return 89;
      case 15: // ~
        return 91;
      case 16: // {|
        return 96;
      case 17: // |}
        return 97;
      case 18: // .
        return 9;
      case 19: // ;
        return 49;
      case 20: // ,
        return 52;
      case 21: // (
        return 73;
      case 22: // )
        return 74;
      case 23: // [
        return 70;
      case 24: // ]
        return 71;
      case 25: // {
        return 36;
      case 26: // }
        return 38;
      case 27: // ANON
        return 78;
      case 28: // IRIREF
        return 8;
      case 29: // PNAME_LN
        return 76;
      case 30: // PNAME_NS
        return 7;
      case 31: // BLANK_NODE_LABEL
        return 26;
      case 32: // LANG_DIR
        return 63;
      case 33:
      case 34: // STRING_LONG
        return 62;
      case 35:
      case 36: // STRING
        return 14;
      case 37: // DOUBLE
        return 67;
      case 38: // DECIMAL
        return 66;
      case 39: // INTEGER
        return 65;
      case 40: // INVALID
        return 99;
      default:
        throw new Error("Unknown lexer rule " + rule);
    }
  }
}

class TurtleLrParser extends LrParser<TurtleValue> {
  public constructor() {
    super(TABLES);
  }

  override tokenValue(text: string): TurtleValue {
    return text;
  }

  override performAction(
    production: number,
    values: TurtleValue[],
  ): TurtleValue {
    const top = values.length - 1;
    switch (production) {
      case 1:
      case 8:
      case 9:
      case 10:
      case 27:
      case 29:
      case 105:
      case 106:
      case 107:
      case 110:
      case 111:
      case 115:
      case 117:
      case 119:
      case 121:
      case 123:
      case 125: {
        return values[top - 0];
      }
      case 2: {
        return addPrefix(values[top - 2] as string, values[top - 1] as string);
      }
      case 3: {
        return addPrefix(values[top - 1] as string, values[top - 0] as string);
      }
      case 4: {
        return setBase(values[top - 1] as string);
      }
      case 5: {
        return setBase(values[top - 0] as string);
      }
      case 6:
      case 25:
      case 30: {
        return values[top - 2];
      }
      case 7:
      case 28:
      case 33:
      case 34:
      case 35:
      case 39:
      case 41: {
        return values[top - 1];
      }
      case 11:
      case 18: {
        return resetGraph();
      }
      case 12: {
        return startStatementSubject(values[top - 0] as RdfTerm);
      }
      case 13:
      case 14: {
        return setGraph(values[top - 0] as RdfTerm);
      }
      case 15: {
        return setGraph(labelledBlankNode(values[top - 0] as string));
      }
      case 16:
      case 17:
      case 24:
      case 36:
      case 37:
      case 38: {
        return setSubject(values[top - 0] as RdfTerm);
      }
      case 19:
      case 21:
      case 22:
      case 23:
      case 26: {
        return finishStatement();
      }
      case 20: {
        return finishStatementAndResetGraph();
      }
      case 31:
      case 32:
      case 47:
      case 49:
      case 50:
      case 51:
      case 52:
      case 53:
      case 54:
      case 55:
      case 56:
      case 57:
      case 58:
      case 59:
      case 85:
      case 86:
      case 87:
      case 88:
      case 89:
      case 90:
      case 94:
      case 95:
      case 96:
      case 97:
      case 98:
      case 99:
      case 100:
      case 101: {
        return (values[top - 0] as RdfTerm);
      }
      case 40: {
        return values[top - 3];
      }
      case 42:
      case 43: {
        return endAnnotation();
      }
      case 44: {
        return emitObject(values[top - 0] as RdfTerm);
      }
      case 45: {
        return setPredicate(values[top - 0] as RdfTerm);
      }
      case 46: {
        return setPredicate(rdfTypeTerm());
      }
      case 48: {
        return rdfTypeTerm();
      }
      case 60:
      case 61: {
        return stringLiteral(values[top - 0] as string);
      }
      case 62:
      case 63: {
        return languageLiteral(
          values[top - 1] as string,
          values[top - 0] as string,
        );
      }
      case 64:
      case 65: {
        return datatypedLiteral(
          values[top - 2] as string,
          values[top - 0] as RdfTerm,
        );
      }
      case 66: {
        return integerLiteral(values[top - 0] as string);
      }
      case 67: {
        return decimalLiteral(values[top - 0] as string);
      }
      case 68: {
        return doubleLiteral(values[top - 0] as string);
      }
      case 69: {
        return booleanLiteral(values[top - 0] as string);
      }
      case 70: {
        return startBlankNodePropertyList();
      }
      case 71: {
        return endBlankNodePropertyList();
      }
      case 72: {
        return startCollection();
      }
      case 73:
      case 74: {
        return endCollection();
      }
      case 75:
      case 76: {
        return collectionAdd(values[top - 0] as RdfTerm);
      }
      case 77: {
        return iriFromToken(values[top - 0] as string);
      }
      case 78:
      case 79: {
        return prefixedName(values[top - 0] as string);
      }
      case 80:
      case 81: {
        return (values[top - 0] as string);
      }
      case 82: {
        return labelledBlankNode(values[top - 0] as string);
      }
      case 83: {
        return freshBlankNode();
      }
      case 84: {
        return makeQuad(
          values[top - 3] as RdfTerm,
          values[top - 2] as RdfTerm,
          values[top - 1] as RdfTerm,
        );
      }
      case 91: {
        return setTripleTerm(
          makeQuad(
            values[top - 2] as RdfTerm,
            values[top - 1] as RdfTerm,
            values[top - 0] as RdfTerm,
          ),
        );
      }
      case 92: {
        return startReifiedTriple();
      }
      case 93: {
        return finishReifiedTriple();
      }
      case 102: {
        return applyReifier(undefined);
      }
      case 103:
      case 104: {
        return applyReifier(values[top - 0] as RdfTerm);
      }
      case 108: {
        return startAnnotationBlock();
      }
      case 109: {
        return endAnnotationBlock();
      }
      case 112:
      case 126: {
        return new Array<string | RdfTerm | undefined>();
      }
      case 113: {
        (values[top - 1] as Array<string | RdfTerm | undefined>).push(
          values[top - 0] as string | undefined,
        );
        return values[top - 1];
      }
      case 114:
      case 116:
      case 118:
      case 120:
      case 122:
      case 124: {
        return undefined;
      }
      case 127: {
        (values[top - 1] as Array<string | RdfTerm | undefined>).push(
          undefined,
        );
        return values[top - 1];
      }
      default:
        throw new Error("Unknown production " + production);
    }
  }
}

/**
 * parseTurtleDocument parses `input`, running the grammar's semantic
 * actions (which write to the parse context) and throwing an `LrParseError`
 * on a syntax error.
 */
export function parseTurtleDocument(input: string): void {
  new TurtleLrParser().parse(new TurtleLexer(input));
}
